package dev.zomboid.remains;import java.util.*;import net.minecraft.world.item.ItemStack;import net.minecraft.resources.ResourceLocation;public class GunAccess{public record Profile(ResourceLocation id,ResourceLocation ammo,int capacity,int tier,Object data){}public record Index(String getType){}public static List<Profile> profiles(){return List.of(new Profile(ResourceLocation.parse("tacz:pistol"),ResourceLocation.parse("tacz:9mm"),12,0,null),new Profile(ResourceLocation.parse("tacz:rifle"),ResourceLocation.parse("tacz:556"),30,2,null));}public static Index index(ResourceLocation id){return new Index(id.toString().contains("pistol")?"pistol":"rifle");}public static Profile describe(ItemStack s){return s.item.id.equals("tacz:modern_kinetic_gun")?profiles().get(s.gun.endsWith("pistol")?0:1):null;}public static ItemStack create(Profile p,int ammo){ItemStack s=fixture.Game.stack("tacz:modern_kinetic_gun");s.gun=p.id.toString();return s;}}
